List<String> names = List.of("Ana", "Bo", "Cleo", "Dan");

// Nothing has run yet — this just describes a pipeline
Stream<String> pipeline = names.stream()
    .filter(n -> n.length() > 2)
    .map(String::toUpperCase);

// Only now does the pipeline actually execute
List<String> result = pipeline.collect(Collectors.toList());
System.out.println(result); // [ANA, CLEO, DAN]

// Reusing the same stream throws IllegalStateException
// pipeline.forEach(System.out::println); // boom

List<String> raw = List.of("3", "1", "4", "1", "5");

// Lambda form
List<Integer> a = raw.stream()
    .map(s -> Integer.parseInt(s))
    .collect(Collectors.toList());

// Equivalent method-reference form — same bytecode target
List<Integer> b = raw.stream()
    .map(Integer::parseInt)
    .collect(Collectors.toList());

raw.forEach(System.out::println); // instance method on a fixed object

record Order(String customer, String category, double amount) {}

List<Order> orders = List.of(
    new Order("Ana", "books", 20.0),
    new Order("Ana", "tech", 150.0),
    new Order("Bo", "books", 15.0)
);

// Total spend per customer
Map<String, Double> totalsByCustomer = orders.stream()
    .collect(Collectors.groupingBy(
        Order::customer,
        Collectors.summingDouble(Order::amount)
    ));
// {Ana=170.0, Bo=15.0}

// Two-level breakdown: customer -> category -> count
Map<String, Map<String, Long>> byCustomerAndCategory = orders.stream()
    .collect(Collectors.groupingBy(
        Order::customer,
        Collectors.groupingBy(Order::category, Collectors.counting())
    ));
